//! ELF, Mach-O (including universal fat binaries), and PE/COFF parsers against
//! independent reference vectors generated by `tooling/debug_obj_vectors.go`.
mod common;

use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/debug-obj-vectors.json")).unwrap()
}

/// Format a Rust string as a Cinch string literal.
fn lit(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\r' => out.push_str("\\r"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Format a JSON array of strings (or null) as a Cinch `List String`.
fn str_list(v: &Value) -> String {
    match v.as_array() {
        None => "Nil".to_string(),
        Some(arr) if arr.is_empty() => "Nil".to_string(),
        Some(arr) => format!(
            "[{}]",
            arr.iter()
                .map(|x| lit(x.as_str().unwrap()))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }
}

/// Format a signed 64-bit integer as a Cinch `I64` expression.
fn i64_expr(n: i64) -> String {
    if n < 0 {
        format!("(wrapping-sub-i64 0 {})", (-n) as u64)
    } else {
        format!("({n} :: I64)")
    }
}

/// Format a signed 16-bit integer as a Cinch `I16` expression.
fn i16_expr(n: i64) -> String {
    if n < 0 {
        format!("(wrapping-sub-i16 0 {})", (-n) as u16)
    } else {
        format!("({n} :: I16)")
    }
}

fn cbool(b: bool) -> &'static str {
    if b {
        "True"
    } else {
        "False"
    }
}

/// Every exported and internal declaration in Data.Elf, Data.MachO, and Data.Pe carries canonical documentation.
#[test]
fn documentation_is_complete() {
    common::assert_documented("Data.Elf", include_str!("../prelude/Data/Elf.cinch"));
    common::assert_documented("Data.MachO", include_str!("../prelude/Data/MachO.cinch"));
    common::assert_documented("Data.Pe", include_str!("../prelude/Data/Pe.cinch"));
}

/// All ELF32/ELF64 little-endian and big-endian vectors, zlib SHF_COMPRESSED sections,
/// symbols, relocations, dynamic tags, and malformed binary rejections match reference outputs.
#[test]
fn elf_vectors_match_reference() {
    let f = fixture();
    let mut rows = Vec::new();

    for c in f["elf"].as_array().unwrap() {
        let progs: Vec<String> = c["progs"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|p| {
                        format!(
                            "(ExpProg {} {} {} {} {} {} {} {})",
                            p["type"],
                            p["flags"],
                            p["off"],
                            p["vaddr"],
                            p["paddr"],
                            p["filesz"],
                            p["memsz"],
                            p["align"]
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        let secs: Vec<String> = c["sections"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpSec {} {} {} {} {} {} {} {} {} {} {} {} {})",
                    lit(s["name"].as_str().unwrap()),
                    s["type"],
                    s["flags"],
                    s["addr"],
                    s["offset"],
                    s["size"],
                    s["file_size"],
                    s["link"],
                    s["info"],
                    s["addralign"],
                    s["entsize"],
                    lit(s["data_hex"].as_str().unwrap()),
                    cbool(s["data_err"].as_bool().unwrap())
                )
            })
            .collect();

        let syms: Vec<String> = c["symbols"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|s| {
                        format!(
                            "(ExpSym {} {} {} {} {} {})",
                            lit(s["name"].as_str().unwrap()),
                            s["info"],
                            s["other"],
                            s["section"],
                            s["value"],
                            s["size"]
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        let dsyms: Vec<String> = c["dyn_symbols"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|s| {
                        format!(
                            "(ExpSym {} {} {} {} {} {})",
                            lit(s["name"].as_str().unwrap()),
                            s["info"],
                            s["other"],
                            s["section"],
                            s["value"],
                            s["size"]
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        let rels: Vec<String> = c["rels"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|r| format!("(ExpRel {} {} {})", r["offset"], r["sym"], r["type"]))
                    .collect()
            })
            .unwrap_or_default();

        let relas: Vec<String> = c["relas"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|r| {
                        format!(
                            "(ExpRela {} {} {} {})",
                            r["offset"],
                            r["sym"],
                            r["type"],
                            i64_expr(r["addend"].as_i64().unwrap())
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        rows.push(format!(
            "check-elf {} {} {} {} {} {} {} {} {} [{}] [{}] {} [{}] {} [{}] {} {} {} {} {} {} [{}] {} [{}]",
            lit(c["hex"].as_str().unwrap()),
            c["class"],
            c["data"],
            c["version"],
            c["osabi"],
            c["abi_version"],
            c["type"],
            c["machine"],
            c["entry"],
            progs.join(", "),
            secs.join(", "),
            cbool(c["has_symbols"].as_bool().unwrap()),
            syms.join(", "),
            cbool(c["has_dyn_symbols"].as_bool().unwrap()),
            dsyms.join(", "),
            str_list(&c["imported_libraries"]),
            str_list(&c["imported_symbols"]),
            str_list(&c["soname"]),
            str_list(&c["runpath"]),
            str_list(&c["rpath"]),
            lit(c["rel_section"].as_str().unwrap()),
            rels.join(", "),
            lit(c["rela_section"].as_str().unwrap()),
            relas.join(", "),
        ));
    }

    for b in f["elf_bad"].as_array().unwrap() {
        rows.push(format!(
            "check-elf-bad {}",
            lit(b["hex"].as_str().unwrap())
        ));
    }
    rows.push(format!(
        "check-elf-extras {}",
        lit(f["elf"][0]["hex"].as_str().unwrap())
    ));
    rows.push("check-elf-helpers".to_string());

    assert!(rows.len() < 200);
    let main_src = format!(
        "{ELF_HELPERS}\n  -- | Execute all ELF conformance checks.\n  main :: Int\n  main = first [{}] 0\n",
        rows.join(",\n    ")
    );
    let dir = common::project(
        "debug_elf",
        &[
            ("Text.Binary.cinch", include_str!("../prelude/Text/Binary.cinch")),
            ("Text.Hex.cinch", include_str!("../prelude/Text/Hex.cinch")),
            ("Data.Bytes.Word.cinch", include_str!("../prelude/Data/Bytes/Word.cinch")),
            ("Text.Flate.cinch", include_str!("../prelude/Text/Flate.cinch")),
            ("Text.Zlib.cinch", include_str!("../prelude/Text/Zlib.cinch")),
            ("Data.Elf.cinch", include_str!("../prelude/Data/Elf.cinch")),
            ("Main.cinch", &main_src),
        ],
    );
    assert_eq!(
        common::run(&dir, "Main.cinch"),
        200,
        "ELF check failed (exit status is 0-based failing row index)"
    );
    common::cleanup(&dir);
}

/// All Mach-O 32/64-bit little/big-endian vectors, universal fat archives, load commands,
/// symbols, libraries, and malformed binary rejections match reference outputs.
#[test]
fn macho_vectors_match_reference() {
    let f = fixture();
    let mut rows = Vec::new();

    for c in f["macho"].as_array().unwrap() {
        let segs: Vec<String> = c["segments"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpSeg {} {} {} {} {} {} {} {} {} {})",
                    s["cmd"],
                    lit(s["name"].as_str().unwrap()),
                    s["addr"],
                    s["memsz"],
                    s["offset"],
                    s["filesz"],
                    s["maxprot"],
                    s["prot"],
                    s["nsect"],
                    s["flag"]
                )
            })
            .collect();

        let secs: Vec<String> = c["sections"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpMSec {} {} {} {} {} {} {} {})",
                    lit(s["name"].as_str().unwrap()),
                    lit(s["seg"].as_str().unwrap()),
                    s["addr"],
                    s["size"],
                    s["offset"],
                    s["align"],
                    s["flags"],
                    lit(s["data_hex"].as_str().unwrap())
                )
            })
            .collect();

        let syms: Vec<String> = c["symbols"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpMSym {} {} {} {} {})",
                    lit(s["name"].as_str().unwrap()),
                    s["type"],
                    s["sect"],
                    s["desc"],
                    s["value"]
                )
            })
            .collect();

        rows.push(format!(
            "check-macho {} {} {} {} {} {} {} {} {} [{}] [{}] [{}] {} {} {} {} {} {}",
            lit(c["hex"].as_str().unwrap()),
            c["magic"],
            cbool(c["big_endian"].as_bool().unwrap()),
            c["cpu"],
            c["subcpu"],
            c["type"],
            c["ncmd"],
            c["cmdsz"],
            c["flags"],
            segs.join(", "),
            secs.join(", "),
            syms.join(", "),
            str_list(&c["imported_libraries"]),
            cbool(c["has_imported_syms"].as_bool().unwrap()),
            str_list(&c["imported_symbols"]),
            str_list(&c["rpaths"]),
            lit(c["uuid_hex"].as_str().unwrap()),
            lit(c["dylinker"].as_str().unwrap()),
        ));
    }

    for fc in f["macho_fat"].as_array().unwrap() {
        let arches: Vec<String> = fc["arches"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| {
                format!(
                    "(ExpFatArch {} {} {} {} {} {} {})",
                    a["cpu"], a["subcpu"], a["offset"], a["size"], a["align"], a["magic"], a["nsect"]
                )
            })
            .collect();
        rows.push(format!(
            "check-macho-fat {} {} [{}]",
            lit(fc["hex"].as_str().unwrap()),
            fc["magic"],
            arches.join(", ")
        ));
    }

    for b in f["macho_bad"].as_array().unwrap() {
        rows.push(format!(
            "check-macho-bad {}",
            lit(b["hex"].as_str().unwrap())
        ));
    }
    for b in f["macho_fat_bad"].as_array().unwrap() {
        rows.push(format!(
            "check-macho-fat-bad {}",
            lit(b["hex"].as_str().unwrap())
        ));
    }

    rows.push(format!(
        "check-macho-extras {}",
        lit(f["macho"][0]["hex"].as_str().unwrap())
    ));
    assert!(rows.len() < 200);
    let main_src = format!(
        "{MACHO_HELPERS}\n  -- | Execute all Mach-O conformance checks.\n  main :: Int\n  main = first [{}] 0\n",
        rows.join(",\n    ")
    );
    let dir = common::project(
        "debug_macho",
        &[
            ("Text.Binary.cinch", include_str!("../prelude/Text/Binary.cinch")),
            ("Text.Hex.cinch", include_str!("../prelude/Text/Hex.cinch")),
            ("Data.MachO.cinch", include_str!("../prelude/Data/MachO.cinch")),
            ("Main.cinch", &main_src),
        ],
    );
    assert_eq!(
        common::run(&dir, "Main.cinch"),
        200,
        "Mach-O check failed (exit status is 0-based failing row index)"
    );
    common::cleanup(&dir);
}

/// All PE32, PE32+, and COFF vectors, sections, COFF symbols, imports, exports,
/// and malformed binary rejections match reference outputs.
#[test]
fn pe_vectors_match_reference() {
    let f = fixture();
    let mut rows = Vec::new();

    for c in f["pe"].as_array().unwrap() {
        let secs: Vec<String> = c["sections"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpPSec {} {} {} {} {} {} {})",
                    lit(s["name"].as_str().unwrap()),
                    s["virtual_size"],
                    s["virtual_address"],
                    s["size"],
                    s["offset"],
                    s["characteristics"],
                    lit(s["data_hex"].as_str().unwrap())
                )
            })
            .collect();

        let syms: Vec<String> = c["symbols"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                format!(
                    "(ExpPSym {} {} {} {} {})",
                    lit(s["name"].as_str().unwrap()),
                    s["value"],
                    i16_expr(s["section_number"].as_i64().unwrap()),
                    s["type"],
                    s["storage_class"]
                )
            })
            .collect();

        let exps: Vec<String> = c["exports"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .map(|e| {
                        format!(
                            "(ExpPExport {} {} {} {})",
                            lit(e["name"].as_str().unwrap()),
                            e["ordinal"],
                            e["rva"],
                            lit(e["forwarder"].as_str().unwrap())
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        rows.push(format!(
            "check-pe {} {} {} {} {} {} {} {} {} [{}] [{}] {} {} {} {} {} [{}]",
            lit(c["hex"].as_str().unwrap()),
            c["machine"],
            c["number_of_sections"],
            c["timestamp"],
            c["characteristics"],
            lit(c["opt_kind"].as_str().unwrap()),
            c["entry_point"],
            c["image_base"],
            c["subsystem"],
            secs.join(", "),
            syms.join(", "),
            str_list(&c["imported_libraries"]),
            str_list(&c["imported_symbols"]),
            c["import_count_all"],
            lit(c["export_dll"].as_str().unwrap()),
            c["export_base"],
            exps.join(", "),
        ));
    }

    for b in f["pe_bad"].as_array().unwrap() {
        rows.push(format!(
            "check-pe-bad {}",
            lit(b["hex"].as_str().unwrap())
        ));
    }
    rows.push(format!(
        "check-pe-extras {}",
        lit(f["pe"][0]["hex"].as_str().unwrap())
    ));

    assert!(rows.len() < 200);
    let main_src = format!(
        "{PE_HELPERS}\n  -- | Execute all PE/COFF conformance checks.\n  main :: Int\n  main = first [{}] 0\n",
        rows.join(",\n    ")
    );
    let dir = common::project(
        "debug_pe",
        &[
            ("Text.Binary.cinch", include_str!("../prelude/Text/Binary.cinch")),
            ("Text.Hex.cinch", include_str!("../prelude/Text/Hex.cinch")),
            ("Data.Pe.cinch", include_str!("../prelude/Data/Pe.cinch")),
            ("Main.cinch", &main_src),
        ],
    );
    assert_eq!(
        common::run(&dir, "Main.cinch"),
        200,
        "PE check failed (exit status is 0-based failing row index)"
    );
    common::cleanup(&dir);
}

const ELF_HELPERS: &str = r#"-- | Conformance runner for Data.Elf.
module Main where

  import Data.Bool
  import Data.Bytes
  import Data.Elf
  import Data.Int
  import Data.List
  import Data.Machine
  import Data.Nat
  import Data.Option
  import Data.Result
  import Data.String
  import Text.Hex (hex-decode, hex-encode)

  -- | Return 200 when every row passes, or the 0-based index of the first failing row.
  first :: List Bool -> Int -> Int
  first xs idx = case xs of
    Nil -> 200
    Cons ok rest -> if ok then first rest (idx + 1) else idx

  -- | Decode a hex fixture string into Bytes.
  unhex :: String -> Bytes
  unhex s = case hex-decode s of
    Ok b -> b
    Err _ -> bytes-new 0

  -- | Compare two String lists element-by-element.
  eq-strs :: List String -> List String -> Bool
  eq-strs a b = case a of
    Nil -> (case b of
      Nil -> True
      Cons _ _ -> False)
    Cons x xs -> case b of
      Nil -> False
      Cons y ys -> x == y && eq-strs xs ys

  -- | Expected program header fields.
  data ExpProg where
    -- | Type, flags, off, vaddr, paddr, filesz, memsz, align.
    ExpProg :: U32 -> U32 -> U64 -> U64 -> U64 -> U64 -> U64 -> U64 -> ExpProg

  -- | Expected section header and data fields.
  data ExpSec where
    -- | Name, type, flags, addr, off, size, file-size, link, info, addralign, entsize, hex, data-err.
    ExpSec :: String -> U32 -> U64 -> U64 -> U64 -> U64 -> U64 -> U32 -> U32 -> U64 -> U64 -> String -> Bool -> ExpSec

  -- | Expected symbol entry.
  data ExpSym where
    -- | Name, info, other, section, value, size.
    ExpSym :: String -> U8 -> U8 -> U32 -> U64 -> U64 -> ExpSym

  -- | Expected REL relocation entry.
  data ExpRel where
    -- | Offset, sym, type.
    ExpRel :: U64 -> U32 -> U32 -> ExpRel

  -- | Expected RELA relocation entry.
  data ExpRela where
    -- | Offset, sym, type, addend.
    ExpRela :: U64 -> U32 -> U32 -> I64 -> ExpRela

  -- | Check program headers list against expected entries.
  check-progs :: List ElfProgHeader -> List ExpProg -> Bool
  check-progs got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons p ps -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpProg t fl off va pa fs ms al ->
          eq-u32 (elf-prog-type-code (elf-prog-type p)) t &&
          eq-u32 (elf-prog-flags p) fl &&
          eq-u64 (elf-prog-offset p) off &&
          eq-u64 (elf-prog-vaddr p) va &&
          eq-u64 (elf-prog-paddr p) pa &&
          eq-u64 (elf-prog-filesz p) fs &&
          eq-u64 (elf-prog-memsz p) ms &&
          eq-u64 (elf-prog-align p) al &&
          check-progs ps ws

  -- | Check sections and section data against expected entries.
  check-secs :: ElfFile -> List ElfSectionHeader -> List ExpSec -> Bool
  check-secs f got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpSec nm typ fl addr off sz fsz lnk inf al esz dhex derr ->
          let meta-ok = (
            elf-section-name s == nm &&
            eq-u32 (elf-section-type-code (elf-section-type s)) typ &&
            eq-u64 (elf-section-flags s) fl &&
            eq-u64 (elf-section-addr s) addr &&
            eq-u64 (elf-section-offset s) off &&
            eq-u64 (elf-section-size s) sz &&
            eq-u64 (elf-section-file-size s) fsz &&
            eq-u32 (elf-section-link s) lnk &&
            eq-u32 (elf-section-info s) inf &&
            eq-u64 (elf-section-addralign s) al &&
            eq-u64 (elf-section-entsize s) esz) in
          let data-ok = (case elf-section-data f s of
            Err _ -> derr
            Ok bytes -> not derr && hex-encode bytes == dhex) in
          meta-ok && data-ok && check-secs f ss ws

  -- | Check symbol list against expected entries.
  check-syms :: List ElfSymbol -> List ExpSym -> Bool
  check-syms got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpSym nm info other sh val sz ->
          elf-sym-name s == nm &&
          eq-u8 (elf-sym-info s) info &&
          eq-u8 (elf-sym-other s) other &&
          eq-u32 (elf-sym-section s) sh &&
          eq-u64 (elf-sym-value s) val &&
          eq-u64 (elf-sym-size s) sz &&
          check-syms ss ws

  -- | Check REL entries.
  check-rels :: List ElfRel -> List ExpRel -> Bool
  check-rels got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons r rs -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpRel off sym typ ->
          eq-u64 (elf-rel-offset r) off &&
          eq-u32 (elf-rel-sym r) sym &&
          eq-u32 (elf-rel-type r) typ &&
          check-rels rs ws

  -- | Check RELA entries.
  check-relas :: List ElfRela -> List ExpRela -> Bool
  check-relas got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons r rs -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpRela off sym typ add ->
          eq-u64 (elf-rela-offset r) off &&
          eq-u32 (elf-rela-sym r) sym &&
          eq-u32 (elf-rela-type r) typ &&
          eq-i64 (elf-rela-addend r) add &&
          check-relas rs ws

  -- | Extract names from imported ELF symbols.
  imp-names :: List ElfImportedSymbol -> List String
  imp-names xs = case xs of
    Nil -> Nil
    Cons s rest -> Cons (elf-imported-name s) (imp-names rest)

  -- | Verify one complete ELF binary fixture.
  check-elf :: String -> U8 -> U8 -> U8 -> U8 -> U8 -> U16 -> U16 -> U64 -> List ExpProg -> List ExpSec -> Bool -> List ExpSym -> Bool -> List ExpSym -> List String -> List String -> List String -> List String -> List String -> String -> List ExpRel -> String -> List ExpRela -> Bool
  check-elf hex-raw cls dat ver osabi abiver typ mach entry want-progs want-secs has-syms want-syms has-dsyms want-dsyms want-libs want-imps want-soname want-runpath want-rpath rel-sec want-rels rela-sec want-relas =
    case elf-parse (unhex hex-raw) of
      Err _ -> False
      Ok f ->
        let h = elf-file-header f in
        let hdr-ok = (
          eq-u8 (elf-class-code (elf-class h)) cls &&
          eq-u8 (elf-data-code (elf-data h)) dat &&
          eq-u8 (elf-version h) ver &&
          eq-u8 (elf-osabi-code (elf-osabi h)) osabi &&
          eq-u8 (elf-abi-version h) abiver &&
          eq-u16 (elf-type-code (elf-type h)) typ &&
          eq-u16 (elf-machine-code (elf-machine h)) mach &&
          eq-u64 (elf-entry h) entry) in
        let progs-ok = check-progs (elf-progs f) want-progs in
        let secs-ok = check-secs f (elf-sections f) want-secs in
        let syms-ok = (case elf-symbols f of
          Err _ -> not has-syms
          Ok ss -> has-syms && check-syms ss want-syms) in
        let dsyms-ok = (case elf-dynamic-symbols f of
          Err _ -> not has-dsyms
          Ok ss -> has-dsyms && check-syms ss want-dsyms) in
        let libs-ok = (case elf-imported-libraries f of
          Err _ -> False
          Ok ls -> eq-strs ls want-libs) in
        let imps-ok = (case elf-imported-symbols f of
          Err _ -> not has-dsyms
          Ok isyms -> eq-strs (imp-names isyms) want-imps) in
        let soname-ok = (case elf-dyn-string f DtSoname of
          Err _ -> False
          Ok vs -> eq-strs vs want-soname) in
        let runpath-ok = (case elf-dyn-string f DtRunpath of
          Err _ -> False
          Ok vs -> eq-strs vs want-runpath) in
        let rpath-ok = (case elf-dyn-string f DtRpath of
          Err _ -> False
          Ok vs -> eq-strs vs want-rpath) in
        let rel-ok = (if string-byte-length rel-sec == 0 then True
          else case elf-section f rel-sec of
            None -> False
            Some s -> case elf-relocations-rel f s of
              Err _ -> False
              Ok rs -> check-rels rs want-rels) in
        let rela-ok = (if string-byte-length rela-sec == 0 then True
          else case elf-section f rela-sec of
            None -> False
            Some s -> case elf-relocations-rela f s of
              Err _ -> False
              Ok rs -> check-relas rs want-relas) in
        hdr-ok && progs-ok && secs-ok && syms-ok && dsyms-ok && libs-ok && imps-ok && soname-ok && runpath-ok && rpath-ok && rel-ok && rela-ok

  -- | Verify a malformed ELF binary is rejected with a non-empty error message.
  check-elf-bad :: String -> Bool
  check-elf-bad hex-raw = case elf-parse (unhex hex-raw) of
    Ok _ -> False
    Err e -> string-byte-length (elf-error-message e) > 0

  -- | Verify ELF symbol info/visibility helpers.
  check-elf-helpers :: Bool
  check-elf-helpers =
    let info = elf-st-info StbGlobal SttFunc in
    eq-u8 info 18 &&
    eq-u8 (elf-sym-bind-code (elf-st-bind info)) 1 &&
    eq-u8 (elf-sym-type-code (elf-st-type info)) 2 &&
    eq-u8 (elf-sym-vis-code (elf-st-visibility 2)) 2

  -- | Verify elf-prog-data, elf-dyn-value, non-string elf-dyn-string refusal, and compression metadata.
  check-elf-extras :: String -> Bool
  check-elf-extras hex-raw = case elf-parse (unhex hex-raw) of
    Err _ -> False
    Ok f ->
      let prog-ok = (case head (elf-progs f) of
        None -> False
        Some p -> case elf-prog-data f p of
          Err _ -> False
          Ok bs -> hex-encode bs == "554889e5b82a0000005dc3") in
      let dynval-ok = (case elf-dyn-value f DtFlags of
        Err _ -> False
        Ok vs -> case vs of
          Cons v Nil -> eq-u64 v 8
          _ -> False) in
      let badtag-ok = (case elf-dyn-string f DtFlags of
        Err (ElfInvalidDynTag _) -> True
        _ -> False) in
      let comp-ok = (case elf-section f ".rodata.z" of
        None -> False
        Some s -> elf-section-compressed s && eq-u32 (elf-section-compression-type s) elf-compress-zlib) in
      let plain-ok = (case elf-section f ".text" of
        None -> False
        Some s -> not (elf-section-compressed s) && eq-u32 (elf-section-compression-type s) 0) in
      prog-ok && dynval-ok && badtag-ok && comp-ok && plain-ok
"#;

const MACHO_HELPERS: &str = r#"-- | Conformance runner for Data.MachO.
module Main where

  import Data.Bool
  import Data.Bytes
  import Data.Int
  import Data.List
  import Data.MachO
  import Data.Machine
  import Data.Nat
  import Data.Option
  import Data.Result
  import Data.String
  import Text.Binary (ByteOrder, LittleEndian, BigEndian)
  import Text.Hex (hex-decode, hex-encode)

  -- | Return 200 when every row passes, or the 0-based index of the first failing row.
  first :: List Bool -> Int -> Int
  first xs idx = case xs of
    Nil -> 200
    Cons ok rest -> if ok then first rest (idx + 1) else idx

  -- | Decode a hex fixture string into Bytes.
  unhex :: String -> Bytes
  unhex s = case hex-decode s of
    Ok b -> b
    Err _ -> bytes-new 0

  -- | Compare two String lists element-by-element.
  eq-strs :: List String -> List String -> Bool
  eq-strs a b = case a of
    Nil -> (case b of
      Nil -> True
      Cons _ _ -> False)
    Cons x xs -> case b of
      Nil -> False
      Cons y ys -> x == y && eq-strs xs ys

  -- | Report whether a ByteOrder is BigEndian.
  is-be :: ByteOrder -> Bool
  is-be bo = case bo of
    BigEndian -> True
    LittleEndian -> False

  -- | Expected segment fields.
  data ExpSeg where
    -- | Cmd, name, addr, memsz, offset, filesz, maxprot, prot, nsect, flag.
    ExpSeg :: U32 -> String -> U64 -> U64 -> U64 -> U64 -> U32 -> U32 -> U32 -> U32 -> ExpSeg

  -- | Expected section fields.
  data ExpMSec where
    -- | Name, seg, addr, size, offset, align, flags, data-hex.
    ExpMSec :: String -> String -> U64 -> U64 -> U32 -> U32 -> U32 -> String -> ExpMSec

  -- | Expected symbol fields.
  data ExpMSym where
    -- | Name, type, sect, desc, value.
    ExpMSym :: String -> U8 -> U8 -> U16 -> U64 -> ExpMSym

  -- | Expected fat architecture entry.
  data ExpFatArch where
    -- | Cpu, subcpu, offset, size, align, inner magic, inner section count.
    ExpFatArch :: U32 -> U32 -> U32 -> U32 -> U32 -> U32 -> Nat -> ExpFatArch

  -- | Check segments against expected entries.
  check-segs :: List MachOSegment -> List ExpSeg -> Bool
  check-segs got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpSeg cmd nm addr ms off fs mp pr ns fl ->
          eq-u32 (seg-cmd s) cmd &&
          seg-name s == nm &&
          eq-u64 (seg-addr s) addr &&
          eq-u64 (seg-memsz s) ms &&
          eq-u64 (seg-offset s) off &&
          eq-u64 (seg-filesz s) fs &&
          eq-u32 (seg-maxprot s) mp &&
          eq-u32 (seg-prot s) pr &&
          eq-u32 (seg-nsect s) ns &&
          eq-u32 (seg-flag s) fl &&
          check-segs ss ws

  -- | Check sections and section data against expected entries.
  check-msecs :: MachOFile -> List MachOSection -> List ExpMSec -> Bool
  check-msecs f got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpMSec nm sg addr sz off al fl dhex ->
          let data-ok = (case macho-section-data f s of
            Err _ -> False
            Ok bs -> hex-encode bs == dhex) in
          sec-name s == nm &&
          sec-seg s == sg &&
          eq-u64 (sec-addr s) addr &&
          eq-u64 (sec-size s) sz &&
          eq-u32 (sec-offset s) off &&
          eq-u32 (sec-align s) al &&
          eq-u32 (sec-flags s) fl &&
          data-ok &&
          check-msecs f ss ws

  -- | Check symbols against expected entries.
  check-msyms :: List MachOSymbol -> List ExpMSym -> Bool
  check-msyms got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpMSym nm typ sect desc val ->
          msym-name s == nm &&
          eq-u8 (msym-type s) typ &&
          eq-u8 (msym-sect s) sect &&
          eq-u16 (msym-desc s) desc &&
          eq-u64 (msym-value s) val &&
          check-msyms ss ws

  -- | Check one Mach-O binary fixture.
  check-macho :: String -> U32 -> Bool -> U32 -> U32 -> U32 -> U32 -> U32 -> U32 -> List ExpSeg -> List ExpMSec -> List ExpMSym -> List String -> Bool -> List String -> List String -> String -> String -> Bool
  check-macho hex-raw magic want-be cpu subcpu typ ncmd cmdsz flags want-segs want-secs want-syms want-libs has-imps want-imps want-rpaths want-uuid want-dylinker =
    case macho-parse (unhex hex-raw) of
      Err _ -> False
      Ok f ->
        let h = macho-header f in
        let hdr-ok = (
          eq-u32 (macho-magic h) magic &&
          (is-be (macho-byte-order h) == want-be) &&
          eq-u32 (macho-cpu-code (macho-cpu h)) cpu &&
          eq-u32 (macho-subcpu h) subcpu &&
          eq-u32 (macho-type-code (macho-file-type h)) typ &&
          eq-u32 (macho-ncmd h) ncmd &&
          eq-u32 (macho-cmdsz h) cmdsz &&
          eq-u32 (macho-flags h) flags) in
        let segs-ok = check-segs (macho-segments f) want-segs in
        let secs-ok = check-msecs f (macho-sections f) want-secs in
        let syms-ok = check-msyms (macho-symbols f) want-syms in
        let libs-ok = eq-strs (macho-imported-libraries f) want-libs in
        let imps-ok = (case macho-imported-symbols f of
          Err _ -> not has-imps
          Ok isyms -> has-imps && eq-strs isyms want-imps) in
        let rpaths-ok = eq-strs (macho-rpaths f) want-rpaths in
        let uuid-ok = (case macho-uuid f of
          None -> string-byte-length want-uuid == 0
          Some u -> hex-encode u == want-uuid) in
        let dylinker-ok = (case macho-dylinker f of
          None -> string-byte-length want-dylinker == 0
          Some dl -> dl == want-dylinker) in
        hdr-ok && segs-ok && secs-ok && syms-ok && libs-ok && imps-ok && rpaths-ok && uuid-ok && dylinker-ok

  -- | Check fat architecture slices against expected entries.
  check-fat-arches :: List MachOFatArch -> List ExpFatArch -> Bool
  check-fat-arches got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons a rest -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpFatArch cpu subcpu off sz al magic nsect ->
          let inner = fat-arch-file a in
          eq-u32 (macho-cpu-code (fat-arch-cpu a)) cpu &&
          eq-u32 (fat-arch-subcpu a) subcpu &&
          eq-u32 (fat-arch-offset a) off &&
          eq-u32 (fat-arch-size a) sz &&
          eq-u32 (fat-arch-align a) al &&
          eq-u32 (macho-magic (macho-header inner)) magic &&
          list-length (macho-sections inner) == nsect &&
          check-fat-arches rest ws

  -- | Check one universal fat binary fixture.
  check-macho-fat :: String -> U32 -> List ExpFatArch -> Bool
  check-macho-fat hex-raw magic want-arches =
    case macho-parse-fat (unhex hex-raw) of
      Err _ -> False
      Ok ff ->
        eq-u32 (macho-fat-magic ff) magic &&
        check-fat-arches (macho-fat-arches ff) want-arches

  -- | Verify a malformed Mach-O binary is rejected with a non-empty error message.
  check-macho-bad :: String -> Bool
  check-macho-bad hex-raw = case macho-parse (unhex hex-raw) of
    Ok _ -> False
    Err e -> string-byte-length (macho-error-message e) > 0

  -- | Verify a malformed fat binary is rejected with a non-empty error message.
  check-macho-fat-bad :: String -> Bool
  check-macho-fat-bad hex-raw = case macho-parse-fat (unhex hex-raw) of
    Ok _ -> False
    Err e -> string-byte-length (macho-error-message e) > 0

  -- | Verify macho-segment, macho-section, macho-segment-data, and macho-dylibs (including LC_ID_DYLIB).
  check-macho-extras :: String -> Bool
  check-macho-extras hex-raw = case macho-parse (unhex hex-raw) of
    Err _ -> False
    Ok f ->
      let seg-ok = (case macho-segment f "__DATA" of
        None -> False
        Some sg -> case macho-segment-data f sg of
          Err _ -> False
          Ok bs -> bytes-len bs == 8) in
      let sec-ok = (case macho-section f "__cstring" of
        None -> False
        Some sc -> case macho-section-data f sc of
          Err _ -> False
          Ok bs -> bytes-len bs == 14) in
      let miss-ok = (case macho-segment f "__MISSING" of
        None -> True
        Some _ -> False) in
      let dylibs-ok = list-length (macho-dylibs f) == 3 && list-length (macho-imported-libraries f) == 2 in
      seg-ok && sec-ok && miss-ok && dylibs-ok
"#;

const PE_HELPERS: &str = r#"-- | Conformance runner for Data.Pe.
module Main where

  import Data.Bool
  import Data.Bytes
  import Data.Int
  import Data.List
  import Data.Machine
  import Data.Nat
  import Data.Option
  import Data.Pe
  import Data.Result
  import Data.String
  import Text.Hex (hex-decode, hex-encode)

  -- | Return 200 when every row passes, or the 0-based index of the first failing row.
  first :: List Bool -> Int -> Int
  first xs idx = case xs of
    Nil -> 200
    Cons ok rest -> if ok then first rest (idx + 1) else idx

  -- | Decode a hex fixture string into Bytes.
  unhex :: String -> Bytes
  unhex s = case hex-decode s of
    Ok b -> b
    Err _ -> bytes-new 0

  -- | Compare two String lists element-by-element.
  eq-strs :: List String -> List String -> Bool
  eq-strs a b = case a of
    Nil -> (case b of
      Nil -> True
      Cons _ _ -> False)
    Cons x xs -> case b of
      Nil -> False
      Cons y ys -> x == y && eq-strs xs ys

  -- | Expected PE section fields.
  data ExpPSec where
    -- | Name, virtual-size, virtual-addr, size, offset, characteristics, data-hex.
    ExpPSec :: String -> U32 -> U32 -> U32 -> U32 -> U32 -> String -> ExpPSec

  -- | Expected PE COFF symbol fields.
  data ExpPSym where
    -- | Name, value, section-number, type, storage-class.
    ExpPSym :: String -> U32 -> I16 -> U16 -> U8 -> ExpPSym

  -- | Expected PE export entry.
  data ExpPExport where
    -- | Name, ordinal, rva, forwarder (empty when none).
    ExpPExport :: String -> U32 -> U32 -> String -> ExpPExport

  -- | Check PE sections and section data against expected entries.
  check-psecs :: PeFile -> List PeSection -> List ExpPSec -> Bool
  check-psecs f got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpPSec nm vs va sz off ch dhex ->
          let data-ok = (case pe-section-data f s of
            Err _ -> False
            Ok bs -> hex-encode bs == dhex) in
          pe-sec-name s == nm &&
          eq-u32 (pe-sec-virtual-size s) vs &&
          eq-u32 (pe-sec-virtual-address s) va &&
          eq-u32 (pe-sec-size s) sz &&
          eq-u32 (pe-sec-offset s) off &&
          eq-u32 (pe-sec-characteristics s) ch &&
          data-ok &&
          check-psecs f ss ws

  -- | Check COFF symbols against expected entries.
  check-psyms :: List PeSymbol -> List ExpPSym -> Bool
  check-psyms got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons s ss -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpPSym nm val sn typ sc ->
          pe-sym-name s == nm &&
          eq-u32 (pe-sym-value s) val &&
          eq-i16 (pe-sym-section-number s) sn &&
          eq-u16 (pe-sym-type s) typ &&
          eq-u8 (pe-sym-storage-class s) sc &&
          check-psyms ss ws

  -- | Check PE export entries against expected entries.
  check-pexps :: List PeExport -> List ExpPExport -> Bool
  check-pexps got want = case got of
    Nil -> (case want of
      Nil -> True
      Cons _ _ -> False)
    Cons e es -> case want of
      Nil -> False
      Cons w ws -> case w of
        ExpPExport nm ord rva fwd ->
          let fwd-ok = (case pe-export-forwarder e of
            None -> string-byte-length fwd == 0
            Some s -> s == fwd) in
          pe-export-name e == nm &&
          eq-u32 (pe-export-ordinal e) ord &&
          eq-u32 (pe-export-rva e) rva &&
          fwd-ok &&
          check-pexps es ws

  -- | Verify one complete PE or COFF binary fixture.
  check-pe :: String -> U16 -> U16 -> U32 -> U16 -> String -> U32 -> U64 -> U16 -> List ExpPSec -> List ExpPSym -> List String -> List String -> Nat -> String -> U32 -> List ExpPExport -> Bool
  check-pe hex-raw mach nsec ts chars opt-kind ep img-base sub want-secs want-syms want-libs want-imps want-imp-all want-exp-dll want-exp-base want-exps =
    case pe-parse (unhex hex-raw) of
      Err _ -> False
      Ok f ->
        let fh = pe-file-header f in
        let fh-ok = (
          eq-u16 (pe-machine-code (pe-fh-machine fh)) mach &&
          eq-u16 (pe-fh-num-sections fh) nsec &&
          eq-u32 (pe-fh-timestamp fh) ts &&
          eq-u16 (pe-fh-characteristics fh) chars) in
        let opt-ok = (case pe-optional-header f of
          PeOptNone -> opt-kind == "none"
          PeOpt32 o ->
            opt-kind == "pe32" &&
            eq-u16 (pe-opt32-magic o) pe-magic-pe32 &&
            eq-u32 (pe-opt32-entry-point o) ep &&
            eq-u64 (u32-to-u64 (pe-opt32-image-base o)) img-base &&
            eq-u16 (pe-subsystem-code (pe-opt32-subsystem o)) sub
          PeOpt64 o ->
            opt-kind == "pe64" &&
            eq-u16 (pe-opt64-magic o) pe-magic-pe64 &&
            eq-u32 (pe-opt64-entry-point o) ep &&
            eq-u64 (pe-opt64-image-base o) img-base &&
            eq-u16 (pe-subsystem-code (pe-opt64-subsystem o)) sub) in
        let secs-ok = check-psecs f (pe-sections f) want-secs in
        let syms-ok = check-psyms (pe-symbols f) want-syms in
        let libs-ok = (case pe-imported-libraries f of
          Err _ -> False
          Ok ls -> eq-strs ls want-libs) in
        let imps-ok = (case pe-imported-symbols f of
          Err _ -> False
          Ok isyms -> eq-strs isyms want-imps) in
        let imp-all-ok = (case pe-imported-symbol-entries f of
          Err _ -> False
          Ok es -> list-length es == want-imp-all) in
        let exps-ok = (case pe-exports f of
          Err _ -> False
          Ok opt-ed -> case opt-ed of
            None -> string-byte-length want-exp-dll == 0
            Some ed ->
              pe-expdir-name ed == want-exp-dll &&
              eq-u32 (pe-expdir-base ed) want-exp-base &&
              check-pexps (pe-expdir-entries ed) want-exps) in
        fh-ok && opt-ok && secs-ok && syms-ok && libs-ok && imps-ok && imp-all-ok && exps-ok

  -- | Verify a malformed PE/COFF binary is rejected with a non-empty error message.
  check-pe-bad :: String -> Bool
  check-pe-bad hex-raw = case pe-parse (unhex hex-raw) of
    Ok _ -> False
    Err e -> string-byte-length (pe-error-message e) > 0

  -- | Check whether any PeImportSymbol matches an ordinal import with the given DLL and ordinal.
  has-ordinal-import :: List PeImportSymbol -> String -> U16 -> Bool
  has-ordinal-import xs dll ord = case xs of
    Nil -> False
    Cons s rest ->
      if pe-impsym-by-ordinal s && pe-impsym-dll s == dll && eq-u16 (pe-impsym-ordinal s) ord then True
      else has-ordinal-import rest dll ord

  -- | Check whether any PeImportSymbol matches a named import with the given DLL, name, and hint.
  has-named-import :: List PeImportSymbol -> String -> String -> U16 -> Bool
  has-named-import xs dll nm hint = case xs of
    Nil -> False
    Cons s rest ->
      if not (pe-impsym-by-ordinal s) && pe-impsym-dll s == dll && pe-impsym-name s == nm && eq-u16 (pe-impsym-hint s) hint then True
      else has-named-import rest dll nm hint

  -- | Verify pe-section, pe-data-directory, pe-import-directories, and ordinal/hint import details.
  check-pe-extras :: String -> Bool
  check-pe-extras hex-raw = case pe-parse (unhex hex-raw) of
    Err _ -> False
    Ok f ->
      let sec-ok = (case pe-section f ".debug_abbrev" of
        None -> False
        Some s -> case pe-section-data f s of
          Err _ -> False
          Ok bs -> hex-encode bs == "0111010000") in
      let dd-ok = (case pe-data-directory f pe-dir-import of
        None -> False
        Some dd -> eq-u32 (pe-dd-virtual-address dd) 0x2000 && eq-u32 (pe-dd-size dd) 60) in
      let dirs-ok = (case pe-import-directories f of
        Err _ -> False
        Ok ds -> list-length ds == 2) in
      let entries-ok = (case pe-imported-symbol-entries f of
        Err _ -> False
        Ok es -> has-ordinal-import es "KERNEL32.dll" 42 && has-named-import es "KERNEL32.dll" "ExitProcess" 10) in
      sec-ok && dd-ok && dirs-ok && entries-ok
"#;
